          ]
        },
        "value": {
          "type": [
            "string",
            "null"
          ]
        },
        "actions": {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "frame": {
          "anyOf": [
            {
              "$ref": "#/$defs/Rect"
            },
            {
