    "ImageTransform": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "originX",
        "originY",
        "scale"
      ],
      "properties": {
        "originX": {
          "type": "number"
        },
        "originY": {
          "type": "number"
        },
        "scale": {
          "type": "number",
          "exclusiveMinimum": 0
        }
      },
      "description": "global point = origin + pixel / scale"
    },
    "ImageArtifact": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "artifactId",
        "mediaType",
        "width",
        "height",
        "byteSize",
        "sha256",
        "transform"
      ],
      "properties": {
        "artifactId": {
          "$ref": "#/$defs/Id"
        },
        "mediaType": {
          "const": "image/png"
        },
        "width": {
          "type": "integer",
          "minimum": 1
        },
        "height": {
          "type": "integer",
          "minimum": 1
        },
        "byteSize": {
          "type": "integer",
          "minimum": 0
        },
        "sha256": {
          "type": "string",
          "pattern": "^[0-9a-f]{64}$"
        },
        "transform": {
          "$ref": "#/$defs/ImageTransform"
        },
        "transient": {
          "type": "boolean",
          "description": "true: kept only briefly (no persist permission for the window); gone at expiresAt or when the window grant ends"
        },
        "expiresAt": {
          "$ref": "#/$defs/Timestamp"
        }
      }
    },
    "ObservedTarget": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "generation",
        "process",
        "windowId",
        "windowFrame",
        "title"
      ],
      "properties": {
        "generation": {
          "type": "integer",
          "minimum": 1
        },
        "process": {
          "$ref": "#/$defs/ProcessIdentity"
        },
        "windowId": {
          "type": "integer",
          "minimum": 1
        },
        "windowFrame": {
          "$ref": "#/$defs/Rect"
        },
        "title": {
          "type": "string"
        }
      }
    },
    "Observation": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "snapshotId",
        "desktopId",
        "capturedAt",
        "screen",
        "target",
        "image",
        "elements"
      ],
      "properties": {
        "snapshotId": {
          "$ref": "#/$defs/Id"
        },
        "desktopId": {
          "$ref": "#/$defs/Id"
        },
        "sessionId": {
          "$ref": "#/$defs/Id"
        },
        "capturedAt": {
          "$ref": "#/$defs/Timestamp"
        },
        "screen": {
          "$ref": "#/$defs/ScreenRef"
        },
        "target": {
          "anyOf": [
            {
              "$ref": "#/$defs/ObservedTarget"
            },
            {
              "type": "null"
            }
          ]
        },
        "image": {
          "anyOf": [
            {
              "$ref": "#/$defs/ImageArtifact"
            },
            {
              "type": "null"
            }
          ]
        },
        "elements": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/Element"
          }
        },
        "coverage": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "screenshot",
            "ax"
          ],
          "description": "what this observation could see: the element read may be partial (truncated walk) or unavailable (deadline passed, a read of the Desktop still running) while the screenshot is complete",
          "properties": {
            "screenshot": {
              "enum": [
                "complete",
                "not_requested"
              ]
            },
            "ax": {
              "enum": [
                "complete",
                "partial",
                "unavailable",
                "not_requested"
              ]
            },
            "axReason": {
              "enum": [
                "deadline",
                "limits",
                "busy",
                "error"
              ]
            }
          }
        }
      }
    },
    "RequestRecord": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "requestId",
        "method",
        "state",
        "acceptedAt"
      ],
      "properties": {
        "requestId": {
          "$ref": "#/$defs/Id"
        },
        "method": {
          "type": "string"
        },
        "state": {
          "enum": [
            "accepted",
            "completed",
            "failed",
            "unknown"
          ]
        },
        "acceptedAt": {
          "$ref": "#/$defs/Timestamp"
        },
        "finishedAt": {
          "$ref": "#/$defs/Timestamp"
        },
        "outcome": {
          "type": "object"
        }
      }
    },
    "ActionTarget": {
      "oneOf": [
        {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "elementRef"
          ],
          "properties": {
            "elementRef": {
              "$ref": "#/$defs/Id"
            }
          }
        },
        {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "imagePoint"
          ],
          "properties": {
            "imagePoint": {
              "type": "object",
              "additionalProperties": false,
              "required": [
                "x",
                "y"
              ],
              "properties": {
                "x": {
                  "type": "number",
                  "minimum": 0
                },
                "y": {
                  "type": "number",
                  "minimum": 0
                }
              }
            }
          }
        }
      ]
    },
    "Action": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "kind"
      ],
      "properties": {
        "kind": {
          "enum": [
            "click",
            "type",
            "key",
            "scroll"
          ]
        },
        "target": {
          "$ref": "#/$defs/ActionTarget"
        },
        "text": {
          "type": "string",
          "minLength": 1,
          "maxLength": 10000
        },
        "key": {
          "type": "string",
          "minLength": 1,
          "maxLength": 32
        },
        "modifiers": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "enum": [
              "cmd",
              "shift",
              "option",
              "ctrl"
            ]
          }
        },
        "button": {
          "enum": [
            "left",
            "right"
          ]
        },
        "count": {
          "type": "integer",
          "minimum": 1,
          "maximum": 2
        },
        "direction": {
          "enum": [
            "up",
            "down",
            "left",
            "right"
          ]
        },
        "amount": {
          "type": "integer",
          "minimum": 1,
          "maximum": 50
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "kind": {
                "const": "click"
              }
            },
            "required": [
              "kind"
            ]
          },
          "then": {
            "required": [
              "target"
            ]
          }
        },
        {
          "if": {
            "properties": {
              "kind": {
                "const": "type"
              }
            },
            "required": [
              "kind"
            ]
          },
          "then": {
            "required": [
              "text"
            ]
          }
        },
        {
          "if": {
            "properties": {
              "kind": {
                "const": "key"
              }
            },
            "required": [
              "kind"
            ]
          },
          "then": {
            "required": [
              "key"
            ]
          }
        },
        {
          "if": {
            "properties": {
              "kind": {
                "const": "scroll"
              }
            },
            "required": [
              "kind"
            ]
          },
          "then": {
            "required": [
              "direction"
            ]
          }
        }
      ]
    },
    "act_params": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "snapshotId",
        "action"
      ],
      "properties": {
        "snapshotId": {
          "$ref": "#/$defs/Id"
        },
        "action": {
          "$ref": "#/$defs/Action"
        }
      }
    },
    "wait_params": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "condition",
        "timeoutMs"
      ],
      "properties": {
        "condition": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "kind"
          ],
          "properties": {
            "kind": {
              "enum": [
                "elementPresent",
                "elementAbsent"
              ]
            },
            "role": {
              "type": "string",
              "minLength": 1
            },
            "label": {
              "type": "string"
            },
            "labelContains": {
              "type": "string",
              "minLength": 1
            }
          }
        },
        "timeoutMs": {
          "type": "integer",
          "minimum": 100,
          "maximum": 60000
        }
      }
    },
    "run_attach_params": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "runId",
        "token"
      ],
      "properties": {
        "runId": {
          "$ref": "#/$defs/Id"
        },
        "token": {
          "type": "string",
          "pattern": "^[0-9a-f]{64}$"
        }
      }
    },
    "run_finish_params": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "runId"
      ],
      "properties": {
        "runId": {
          "$ref": "#/$defs/Id"
        },
        "exitCode": {
          "type": "integer"
        }
      }
    },
    "run_ref_params": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "runId"
      ],
      "properties": {
        "runId": {
          "$ref": "#/$defs/Id"
        }
      }
    },
    "run_events_params": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "runId"
      ],
      "properties": {
        "runId": {
          "$ref": "#/$defs/Id"
        },
        "after": {
          "type": "integer",
          "minimum": 0
        },
        "limit": {
          "type": "integer",
          "minimum": 1,
          "maximum": 500
        }
      }
    },
    "run_wait_params": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "runId",
        "timeoutMs"
      ],
      "properties": {
        "runId": {
          "$ref": "#/$defs/Id"
        },
        "timeoutMs": {
          "type": "integer",
          "minimum": 0,
          "maximum": 600000
        }
      }
    },
    "ActionReceipt": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "receiptId",
        "requestId",
        "runId",
        "desktopId",
        "sessionId",
        "snapshotId",
        "delivery",
        "execution",
        "verification",
        "route",
        "target",
        "timing"
      ],
      "properties": {
        "receiptId": {
          "$ref": "#/$defs/Id"
        },
        "requestId": {
          "$ref": "#/$defs/Id"
        },
        "runId": {
          "$ref": "#/$defs/Id"
        },
        "desktopId": {
          "$ref": "#/$defs/Id"
        },
        "sessionId": {
          "$ref": "#/$defs/Id"
        },
        "snapshotId": {
          "$ref": "#/$defs/Id"
        },
        "delivery": {
          "enum": [
            "dispatched",
            "not_dispatched",
            "unknown"
          ]
        },
        "execution": {
          "enum": [
            "completed",
            "failed",
            "unknown"
          ]
        },
        "verification": {
          "const": "not_requested"
        },
        "businessResult": {
          "const": "not_evaluated",
          "description": "delivery is not effect; a later observation or the caller establishes the effect"
        },
        "reason": {
          "$ref": "#/$defs/FailureReason",
          "description": "why the action was not delivered, failed or has an unknown outcome; absent when delivered"
        },
        "route": {
          "type": [
            "string",
            "null"
          ]
        },
        "target": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "generation",
            "process",
            "windowId",
            "elementRef",
            "point"
          ],
          "properties": {
            "generation": {
              "type": "integer",
              "minimum": 1
            },
            "process": {
              "$ref": "#/$defs/ProcessIdentity"
            },
            "windowId": {
              "type": "integer",
              "minimum": 1
            },
            "elementRef": {
              "anyOf": [
                {
                  "$ref": "#/$defs/Id"
                },
                {
                  "type": "null"
                }
              ]
            },
            "point": {
              "anyOf": [
                {
                  "type": "object",
                  "additionalProperties": false,
                  "required": [
                    "x",
                    "y"
                  ],
                  "properties": {
                    "x": {
                      "type": "number"
                    },
                    "y": {
                      "type": "number"
                    }
                  }
                },
                {
                  "type": "null"
                }
              ]
            }
          }
        },
        "timing": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "acceptedAt",
            "dispatchedAt",
            "completedAt"
          ],
          "properties": {
            "acceptedAt": {
              "$ref": "#/$defs/Timestamp"
            },
            "dispatchedAt": {
              "anyOf": [
                {
                  "$ref": "#/$defs/Timestamp"
                },
                {
                  "type": "null"
                }
              ]
            },
            "completedAt": {
              "$ref": "#/$defs/Timestamp"
            }
          }
        }
      }
    },
    "WaitResult": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "satisfied",
        "snapshotId",
        "matches"
      ],
      "properties": {
        "satisfied": {
          "const": true
        },
        "snapshotId": {
          "$ref": "#/$defs/Id"
        },
        "matches": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/Element"
          }
        }
      }
    },
    "Run": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "runId",
        "kind",
        "origin",
        "ownership",
        "lifetime",
        "clientId",
        "connectionId",
        "sessionId",
        "desktopId",
        "phase",
        "outcome",
        "quiescence",
        "closingReason",
        "revision",
        "createdAt",
        "receipts",
        "unknownActions"
      ],
      "properties": {
        "runId": {
          "$ref": "#/$defs/Id"
        },
        "kind": {
          "enum": [
            "act",
            "exec",
            "unit"
          ]
        },
        "origin": {
          "enum": [
            "agent_hub",
            "gui_explorer",
            "workflow_replay",
            "user"
          ]
        },
        "ownership": {
          "enum": [
            "external_client",
            "platform"
          ]
        },
        "lifetime": {
          "enum": [
            "connection_scoped",
            "platform_durable"
          ]
        },
        "clientId": {
          "type": [
            "string",
            "null"
          ]
        },
        "connectionId": {
          "type": [
            "string",
            "null"
          ]
        },
        "sessionId": {
          "$ref": "#/$defs/Id"
        },
        "desktopId": {
          "$ref": "#/$defs/Id"
        },
        "phase": {
          "enum": [
            "queued",
            "running",
            "waiting_approval",
            "waiting_input",
            "stopping",
            "ended"
          ]
        },
        "outcome": {
          "enum": [
            "success",
            "failed",
            "cancelled",
            "unknown",
            null
          ]
        },
        "quiescence": {
          "enum": [
            "not_confirmed",
            "pending",
            "confirmed"
          ]
        },
        "closingReason": {
          "type": [
            "string",
            "null"
          ]
        },
        "revision": {
          "type": "integer",
          "minimum": 1
        },
        "createdAt": {
          "$ref": "#/$defs/Timestamp"
        },
        "endedAt": {
          "$ref": "#/$defs/Timestamp"
        },
        "receipts": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/Id"
          }
        },
        "unknownActions": {
          "type": "integer",
          "minimum": 0
        },
        "unit": {
          "$ref": "#/$defs/RunUnit"
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "phase": {
                "const": "ended"
              }
            }
          },
          "then": {
            "properties": {
              "quiescence": {
                "const": "confirmed"
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "ownership": {
                "const": "external_client"
              }
            }
          },
          "then": {
            "properties": {
              "lifetime": {
                "const": "connection_scoped"
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "ownership": {
                "const": "platform"
              }
            }
          },
          "then": {
            "properties": {
              "lifetime": {
                "const": "platform_durable"
              }
            }
          }
        }
      ]
    },
    "RunStart": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "run",
        "attachToken"
      ],
      "properties": {
        "run": {
          "$ref": "#/$defs/Run"
        },
        "attachToken": {
          "type": "string",
          "pattern": "^[0-9a-f]{64}$",
          "writeOnly": true
        }
      }
    },
    "RunEvent": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "runId",
        "sequence",
        "at",
        "type",
        "data"
      ],
      "properties": {
        "runId": {
          "$ref": "#/$defs/Id"
        },
        "sequence": {
          "type": "integer",
          "minimum": 1
        },
        "at": {
          "$ref": "#/$defs/Timestamp"
        },
        "type": {
          "type": "string"
        },
        "data": {
          "type": "object"
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "type": {
                "pattern": "^(run|action|stop)\\."
              }
            },
            "required": [
              "type"
            ]
          },
          "then": {
            "$ref": "#/$defs/PlatformRunEvent"
          }
        }
      ]
    },
    "RunEvents": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "events",
        "next",
        "ended"
      ],
      "properties": {
        "events": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/RunEvent"
          }
        },
        "next": {
          "type": "integer",
          "minimum": 0
        },
        "ended": {
          "type": "boolean"
        }
      }
    },
    "CancelReceipt": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "cancelRequest",
        "execution"
      ],
      "properties": {
        "cancelRequest": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "accepted",
            "scope"
          ],
          "properties": {
            "accepted": {
              "const": true
            },
            "scope": {
              "type": "object",
              "additionalProperties": false,
              "required": [
                "kind",
                "id"
              ],
              "properties": {
                "kind": {
                  "const": "run"
                },
                "id": {
                  "$ref": "#/$defs/Id"
                }
              }
            }
          }
        },
        "execution": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "phase",
            "quiescence",
            "outcome",
            "revision"
          ],
          "properties": {
            "phase": {
              "type": "string"
            },
            "quiescence": {
              "type": "string"
            },
            "outcome": {
              "type": [
                "string",
                "null"
              ]
            },
            "revision": {
              "type": "integer"
            }
          }
        },
        "alreadyTerminal": {
          "type": "boolean"
        }
      }
    },
    "run_start_params": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "lifetime": {
          "enum": [
            "connection_scoped",
            "platform_durable"
          ],
          "description": "accepted only to refuse escalation explicitly"
        },
        "ownership": {
          "enum": [
            "external_client",
            "platform"
          ]
        },
        "origin": {
          "enum": [
            "agent_hub",
            "gui_explorer",
            "workflow_replay",
            "user"
          ]
        }
      }
    },
    "run_list_params": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
