    "ObservationFrame": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "apiVersion",
        "subscriptionId",
        "sequence",
        "type",
        "status"
      ],
      "properties": {
        "apiVersion": {
          "$ref": "#/$defs/ApiVersion"
        },
        "subscriptionId": {
          "$ref": "#/$defs/Id"
        },
        "sequence": {
          "type": "integer",
          "minimum": 1
        },
        "type": {
          "const": "observation.frame"
        },
        "status": {
          "enum": [
            "ready",
            "paused"
          ]
        },
        "frame": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "image",
            "screen",
            "target",
            "capturedAt"
          ],
          "properties": {
            "image": {
              "anyOf": [
                {
                  "$ref": "#/$defs/ImageArtifact"
                },
                {
                  "type": "null"
                }
              ]
            },
            "screen": {
              "$ref": "#/$defs/ScreenRef"
            },
            "target": {
              "anyOf": [
                {
                  "$ref": "#/$defs/ObservedTarget"
                },
                {
                  "type": "null"
                }
              ]
            },
            "capturedAt": {
              "$ref": "#/$defs/Timestamp"
            }
          }
        },
        "error": {
          "$ref": "#/$defs/Error"
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "status": {
                "const": "ready"
              }
            }
          },
          "then": {
            "required": [
              "frame"
            ],
            "not": {
              "required": [
                "error"
              ]
            }
          }
        },
        {
          "if": {
            "properties": {
              "status": {
                "const": "paused"
              }
            }
          },
          "then": {
            "required": [
              "error"
            ],
            "not": {
              "required": [
                "frame"
              ]
            }
          }
        }
      ]
    },
